package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="antecedentes_medicos") public class AntecedenteMedico { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @Column(name="paciente_id",nullable=false) private UUID pacienteId; @Column(nullable=false) private String tipo; @Column(nullable=false,columnDefinition="TEXT") private String descripcion; @Column(name="fecha_aproximada") private LocalDate fechaAproximada; @Column(name="fecha_desconocida") private boolean fechaDesconocida; private String estado="ACTIVO"; @Column(name="relacion_familiar") private String relacionFamiliar; @Column(columnDefinition="TEXT") private String observaciones; @Column(name="registrado_por") private UUID registradoPor; @Column(name="creado_en") private LocalDateTime creadoEn; @Column(name="actualizado_en") private LocalDateTime actualizadoEn; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public String getTipo(){return tipo;} public String getDescripcion(){return descripcion;} public LocalDate getFechaAproximada(){return fechaAproximada;} public boolean isFechaDesconocida(){return fechaDesconocida;} public String getEstado(){return estado;} public String getRelacionFamiliar(){return relacionFamiliar;} public String getObservaciones(){return observaciones;} public UUID getRegistradoPor(){return registradoPor;} public LocalDateTime getCreadoEn(){return creadoEn;} public LocalDateTime getActualizadoEn(){return actualizadoEn;} public void setEmpresaId(UUID v){empresaId=v;} public void setPacienteId(UUID v){pacienteId=v;} public void setTipo(String v){tipo=v;} public void setDescripcion(String v){descripcion=v;} public void setFechaAproximada(LocalDate v){fechaAproximada=v;} public void setFechaDesconocida(boolean v){fechaDesconocida=v;} public void setEstado(String v){estado=v;} public void setRelacionFamiliar(String v){relacionFamiliar=v;} public void setObservaciones(String v){observaciones=v;} public void setRegistradoPor(UUID v){registradoPor=v;} public void setCreadoEn(LocalDateTime v){creadoEn=v;} public void setActualizadoEn(LocalDateTime v){actualizadoEn=v;} }
